FOR UPDATE

SELECT 
FROM practice_code_review review
WHERE review.user_id = #{userId}
  AND review.id IN
  #{reviewId}
ORDER BY review.id ASC

WITH latest AS (
  SELECT DISTINCT ON (review.problem_slug) review.id
  FROM practice_code_review review
  WHERE review.user_id = #{userId}

    AND review.problem_slug NOT IN
    #{problemSlug}

  ORDER BY review.problem_slug ASC, review.created_at DESC, review.id DESC
)
SELECT 
FROM practice_code_review review
JOIN latest ON latest.id = review.id
ORDER BY review.created_at DESC, review.id DESC
LIMIT #{limit}

SELECT *
FROM (
  SELECT 
  FROM practice_code_review review
  WHERE review.user_id = #{userId}
    AND review.problem_slug = #{problemSlug}
  ORDER BY review.created_at DESC, review.id DESC
  LIMIT LEAST(#{limit}, 5)
) history
ORDER BY history.created_at ASC, history.review_id ASC

SELECT 
FROM practice_code_review review
WHERE review.user_id = #{userId}
  AND review.id IN
  #{reviewId}
ORDER BY review.id ASC
